css:
/* Approved mockups/card-proposal.css tokens and component geometry. */
:root {
 --paper:#eaf5fc; --canvas:#d9ecff; --ink:#0a2457; --secondary:#344f73;
 --accent:#005b98; --line:#a8c8e2; --note:#d9ecff; --hover:#cce8fb;
 color-scheme:light;
 scrollbar-color:var(--line) var(--canvas); scrollbar-width:auto;
}
:root.nightMode, :root.night_mode, .nightMode, .night_mode,
:root[data-hebleo-mode="dark"], body.card[data-hebleo-mode="dark"] {
 --paper:#142238; --canvas:#0d1728; --ink:#f7faff; --secondary:#c2d3ea;
 --accent:#8fd8f6; --line:#425a79; --note:#1c324d; --hover:#25415f;
 color-scheme:dark;
}
:root[data-hebleo-mode="light"], body.card[data-hebleo-mode="light"] {
 --paper:#eaf5fc; --canvas:#d9ecff; --ink:#0a2457; --secondary:#344f73;
 --accent:#005b98; --line:#a8c8e2; --note:#d9ecff; --hover:#cce8fb;
 color-scheme:light;
}
html:root { min-height:100%; background:transparent; scrollbar-color:var(--line) var(--canvas); scrollbar-width:auto; }
* { box-sizing:border-box; }
body.card { min-height:100vh; margin:0; padding:20px; background:var(--canvas); color:var(--ink); font-family:"Segoe UI",Arial,sans-serif; font-size:16px; line-height:1.5; text-align:left; overflow-wrap:anywhere; }
#qa { background:transparent; }
[hidden] { display:none !important; }
button { font:inherit; cursor:pointer; }
button:focus-visible { outline:3px solid var(--accent); outline-offset:4px; }
.hc-card { max-width:720px; margin:0 auto; }
.hc-card { position: relative; padding: 24px; border-radius: 8px; background: var(--paper); border: 1px solid var(--line); }
.hc-header { display: grid; gap: 12px; }
.hc-brand-row, .hc-meta-row { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.hc-brand-row { min-height: 44px; }
.hc-theme-control { position: absolute; right: 8px; top: 6px; }
.hc-theme-input { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.hc-theme-switch { display: inline-flex; width: 48px; min-height: 44px; align-items: center; cursor: pointer; border-radius: 6px; }
.hc-theme-icon { display: block; width: 14px; height: 14px; flex: 0 0 14px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.hc-theme-track { display: inline-block; position: relative; width: 48px; height: 28px; flex: 0 0 48px; border: 1px solid var(--accent); border-radius: 20px; background: transparent; }
.hc-theme-thumb { display: flex; align-items: center; justify-content: center; position: absolute; left: 3px; top: 3px; width: 20px; height: 20px; border-radius: 50%; background: var(--accent); color: var(--paper); transition: transform .15s ease; }
.hc-theme-dark { display: none; }
.hc-theme-input:checked + .hc-theme-switch .hc-theme-track { background: var(--accent); }
.hc-theme-input:checked + .hc-theme-switch .hc-theme-thumb { transform: translateX(20px); background: var(--paper); color: var(--accent); }
.hc-theme-input:checked + .hc-theme-switch .hc-theme-light { display: none; }
.hc-theme-input:checked + .hc-theme-switch .hc-theme-dark { display: block; }
.hc-theme-switch:hover .hc-theme-track { box-shadow: 0 0 0 3px var(--hover); }
.hc-theme-input:focus-visible + .hc-theme-switch { outline: 3px solid var(--accent); outline-offset: 4px; }
.hc-type { color: var(--secondary); font-size: 14px; font-weight: 600; }
.hc-logo { display: block; width: 116px; height: auto; aspect-ratio: 3693 / 1198; object-fit: contain; }
.hc-nikkud { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.hc-toggle {
  display: inline-flex; justify-content: center; align-items: center; min-height: 44px; padding: 8px 10px;
  border: 1px solid var(--line); border-radius: 8px; color: var(--accent); cursor: pointer;
  font-size: 14px; white-space: nowrap;
}
.hc-toggle:hover { background: var(--hover); }
.hc-nikkud:focus-visible + .hc-header .hc-toggle { outline: 3px solid var(--accent); outline-offset: 3px; }
.hc-hide-label, .hc-pointed { display: none; }
.hc-nikkud:checked + .hc-header .hc-show-label { display: none; }
.hc-nikkud:checked + .hc-header .hc-hide-label { display: inline; }
.hc-nikkud:checked ~ .hc-content .hc-pointed { display: inline; }
.hc-nikkud:checked ~ .hc-content .hc-unpointed { display: none; }
.hc-hebrew { direction: rtl; unicode-bidi: isolate; font-family: "Segoe UI", Arial, sans-serif; }
.hc-prompt { padding: 16px 0 24px; text-align: center; }
.hc-word { font-size: 64px; line-height: 1.5; font-weight: 500; }
.hc-english { font-size: 28px; line-height: 1.4; white-space: pre-wrap; }
.hc-answer { border-top: 1px solid var(--line); padding-top: 20px; }
.hc-solution { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 12px; margin-bottom: 24px; text-align: center; }
.hc-solution .hc-word { font-size: 48px; }
.hc-notes { background: var(--note); border-left: 3px solid var(--accent); padding: 16px 20px; margin: 0 0 24px; border-radius: 0 6px 6px 0; }
.hc-section-heading { font-size: 16px; line-height: 1.5; margin: 0 0 8px; font-weight: 600; color: var(--ink); }
.hc-notes p { font-size: 16px; line-height: 1.65; white-space: pre-wrap; margin: 0; }
.hc-notes p + p { margin-top: 16px; }
.hc-forms { margin: 0; }
.hc-form-list { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 160px), 1fr)); gap: 0 20px; }
.hc-form { border-top: 1px solid var(--line); padding: 14px 0 8px; }
.hc-form-label { color: var(--secondary); font-size: 14px; margin: 0 0 6px; }
.hc-form-value { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.hc-form .hc-hebrew { font-size: 32px; line-height: 1.65; }
/* One visual adapter for native base replay and manual form buttons.
   Form buttons intentionally do not acquire native replay classes/handlers. */
.hc-card :is(.hc-audio .replay-button, .hc-audio .soundLink, .hc-play) {
  display: flex; align-items: center; justify-content: center; flex: 0 0 44px;
  box-sizing: border-box; width: 44px; min-width: 44px; height: 44px; min-height: 44px;
  padding: 0; margin: 0; border: 0; border-radius: 50%; background: transparent;
  color: var(--accent); font: inherit; line-height: 1; text-decoration: none;
  vertical-align: middle; cursor: pointer; appearance: none; box-shadow: none;
}
.hc-card :is(.hc-audio .replay-button, .hc-audio .soundLink, .hc-play) svg {
  display: block; width: 32px; height: 32px; margin: 0; padding: 0;
  fill: none; stroke: none; overflow: visible;
}
.hc-card :is(.hc-audio .replay-button, .hc-audio .soundLink, .hc-play) svg circle {
  fill: var(--paper); stroke: var(--line); stroke-width: 2;
}
.hc-card :is(.hc-audio .replay-button, .hc-audio .soundLink, .hc-play) svg path {
  fill: var(--accent); stroke: none;
}
.hc-card :is(.hc-audio .replay-button, .hc-audio .soundLink, .hc-play):hover svg circle {
  fill: var(--hover); stroke: var(--accent);
}
.hc-card :is(.hc-audio .replay-button, .hc-audio .soundLink, .hc-play):focus-visible {
  outline: 3px solid var(--accent); outline-offset: 4px;
}
.hc-card :is(.hc-audio .replay-button, .hc-audio .soundLink, .hc-play):active { transform: scale(.96); }
@media (max-width: 520px) {
  body { padding: 16px; }
  .review-canvas { padding: 8px; }
  .hc-card { padding: 16px; }
  .hc-header { gap: 8px; }
  .hc-logo { width: 88px; }
  .hc-type { font-size: 12px; }
  .hc-toggle { font-size: 12px; padding: 8px; }
  .hc-word { font-size: 56px; }
  .hc-notes { padding: 12px 16px; }
  .hc-form-list { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto; transition: none; animation: none; } }
@media (forced-colors: active) { .hc-card, .hc-play, .hc-toggle, .hc-notes { border: 1px solid CanvasText; } .hc-theme-track { border-color: ButtonText; } .hc-theme-thumb { background: ButtonText; color: ButtonFace; } .hc-theme-input:checked + .hc-theme-switch .hc-theme-track { background: Highlight; } .hc-theme-input:checked + .hc-theme-switch .hc-theme-thumb { background: HighlightText; color: Highlight; } }
::-webkit-scrollbar { width: 12px; height: 12px; }
::-webkit-scrollbar-thumb { background: #7b8da5; border: 3px solid transparent; background-clip: padding-box; border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background-color: #526174; }
::-webkit-scrollbar-thumb:active { background-color: #344f73; }
::-webkit-scrollbar-track { background: transparent; }

.hc-logo-dark { display:none; }
.nightMode .hc-logo-light, .night_mode .hc-logo-light { display:none; }
.nightMode .hc-logo-dark, .night_mode .hc-logo-dark { display:block; }
[data-hebleo-mode="light"] .hc-logo-light { display:block; }
[data-hebleo-mode="light"] .hc-logo-dark { display:none; }
[data-hebleo-mode="dark"] .hc-logo-light { display:none; }
[data-hebleo-mode="dark"] .hc-logo-dark { display:block; }
.hc-logo { max-width:116px !important; max-height:none !important; }
.hc-form-value > .hc-hebrew { min-width:0; overflow-wrap:anywhere; }
.hc-audio-status { margin:0; font-size:14px; color:var(--secondary); }
.hc-audio-status:empty { display:none; }
@media (max-width:520px) { body.card { padding:8px; } .hc-logo { max-width:88px !important; } }
.hc-card:has(.hc-verb-forms){max-width:820px}
.verb-sections{margin-top:20px}.verb-section{border:1px solid var(--line);border-radius:6px;margin:10px 0;overflow:hidden}
.section-toggle{display:flex;align-items:center;gap:10px;width:100%;text-align:left;color:var(--ink);border:0;border-radius:0;cursor:pointer;min-height:48px;padding:12px 16px;font-weight:600;background:var(--note)}
.section-toggle:hover{background:var(--hover)}.section-arrow{width:12px;flex:none}
.section-toggle:focus-visible,.paradigm-scroll:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}
.section-toggle[aria-expanded=true]{border-bottom:1px solid var(--line)}
.slide-body{padding:12px}.paradigm-scroll{overflow-x:auto;max-width:100%;scrollbar-width:thin;scrollbar-color:var(--accent) var(--paper)}
.slide-body>.he-form{display:block;text-align:center;font-size:30px;line-height:1.8;padding:8px}
.reference-paradigm{border-collapse:collapse;table-layout:fixed;width:100%;min-width:540px;text-align:center}
.reference-paradigm th,.reference-paradigm td{padding:10px 6px;vertical-align:middle;border-bottom:1px solid var(--line)}
.reference-paradigm thead{background:var(--note)}.reference-paradigm th{font-size:12px;font-weight:600}
.reference-paradigm th.person-col{width:50px}.reference-paradigm tbody th{font-size:12px;color:var(--secondary);background:var(--note)}
.reference-paradigm td.number-start{border-left:1px solid var(--line)}
.reference-paradigm .form-pair{display:flex;flex-direction:column;align-items:center;gap:4px;white-space:nowrap}
.reference-paradigm .he-form{font-size:25px;line-height:1.7;font-weight:400;white-space:nowrap}.form-pronoun{font-size:12px;color:var(--secondary)}
.he-form.citation{background:#fff1b8;border-radius:3px;padding:0 3px}.teaching-blue{color:#0065ac}.teaching-green{color:#087a42}.teaching-purple{color:#7731b8}.teaching-orange{color:#9c4b09}.teaching-red{color:#a6192e}.source-stress{font-weight:700}
[data-hebleo-mode=dark] .he-form.citation{background:#594919}[data-hebleo-mode=dark] .teaching-blue{color:#72c4ff}[data-hebleo-mode=dark] .teaching-green{color:#79dfad}[data-hebleo-mode=dark] .teaching-purple{color:#d1a7ff}[data-hebleo-mode=dark] .teaching-orange{color:#ffbf80}[data-hebleo-mode=dark] .teaching-red{color:#ff9aa8}
.infinitive-row{display:flex;align-items:center;justify-content:space-between;padding:14px 0;margin-top:12px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.infinitive-row bdi{font-size:30px}.infinitive-row>span{font-weight:600;font-size:14px}
.scroll-hint{font-size:12px;color:var(--secondary);margin:0 0 8px;display:none}.reading-key{font-size:13px;color:var(--secondary);margin-top:14px}.reading-key summary{cursor:pointer;padding:8px 0}.reading-key li{margin:6px 0}.hc-notes{margin-top:20px}.empty-form{margin:6px 0;font-size:14px;color:var(--secondary)}
@media(max-width:640px){.scroll-hint{display:block}.slide-body{padding:8px}.hc-word.citation-pair{font-size:38px}.hc-card{padding:16px}}

/* Approved adjective/preposition layouts; original audio controls are shared. */
.hc-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.hc-adjective-table{width:100%;border-collapse:collapse;table-layout:fixed}
.hc-adjective-table th,.hc-adjective-table td{padding:10px 6px;border-bottom:1px solid var(--line);text-align:center;vertical-align:middle}
.hc-adjective-table thead th{font-size:13px;color:var(--secondary)}.hc-adjective-table th:first-child{width:60px;white-space:nowrap;font-size:12px}
.hc-adjective-table tbody th{font-size:14px}.hc-adjective-table .hc-hebrew{font-size:28px;line-height:1.7}
.hc-adjective-table .form-pair,.form-slot{display:flex;flex-direction:column;align-items:center;gap:4px;min-width:0}
.hc-adjective-table abbr{text-decoration:none}.hc-empty{font-size:14px;color:var(--secondary)}
.pair-groups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.number-group{min-width:0}.number-group h3{font-size:14px;color:var(--secondary);margin:0 0 8px}
.pronoun-list{list-style:none;padding:0;margin:0}.pronoun-list li{padding:8px 0;border-top:1px solid var(--line);text-align:center}
.pronoun-list .hc-hebrew{font-size:28px;line-height:1.7}.form-slot>.form-pronoun{font-size:13px}
.reference-paradigm .hc-hebrew{font-size:25px;line-height:1.7;white-space:nowrap;font-weight:400}
.reference-paradigm .hc-hebrew.citation{background:#fff1b8;border-radius:3px;padding:0 3px}
[data-hebleo-mode=dark] .reference-paradigm .hc-hebrew.citation{background:#594919}
.hc-nominal{text-align:center;font-size:30px;padding:8px}.infinitive-row .hc-hebrew{font-size:30px}
.hc-extra-forms{margin-top:16px}.reference-paradigm .citation-cell{background:var(--note)}
.hc-verb-forms+.hc-notes{margin-top:20px}
